\label{lem:moja-equil1}
Let $ \bm{x} = [ (\bm{x}_1)^T \, \ldots  (\bm{x}_1)^T ]^T$ be an equilibrium point of the system \eqref{eq:update-moja}. 
Then $ \bm{x} $  belongs to one of the following classes:
\begin{enumerate}
\item consensus: $ \bm{x}_i = \bm{v}_k $ $ \forall \, i$, and $ k=1, \ldots, d$;
\item bipartite consensus: $ \bm{x}_i = \pm \bm{v}_k $ $ \forall \, i$ and $ k=1, \ldots, d$;
\item polygonal equilibria: $ \{ {\bm{x}_i \in \mathbb{S}^{d-1}} \; \text{s.t.} \;  {F_V} \sum_{j=1}^n  \bm{x}_j =0\}. $
\end{enumerate}

\label{lem:Jac-moja}
The Jacobian $ J(\bm{x}) $ of the system \eqref{eq:update-moja} has the following blocks:
\begin{equation}
\begin{split}
 \frac{\partial f_i(\bm{x})}{\partial \bm{x}_h}   =& \frac{\frac{\eta}{n} {F_V}}{\| \bm{x}_i +  \frac{\eta}{n} {F_V} \sum_j \bm{x}_j \| } 
-  ( \bm{x}_i + \frac{\eta}{n} {F_V} \sum_j \bm{x}_j ) \cdot \\
& \cdot \frac{ \frac{\eta}{n} \left( \bm{x}_i^T {F_V} + \frac{\eta}{n} \left( \sum_j \bm{x}_j^T {F_V}^T (I - \bm{x}_i \bm{x}_i^T ){F_V} \right) \right) }
{\| \bm{x}_i +  \frac{\eta}{n} {F_V} \sum_j \bm{x}_j \|^2 } \\
& + \left( \frac{I}{\| \bm{x}_i +  \frac{\eta}{n} {F_V} \sum_j \bm{x}_j \| }  
-  ( \bm{x}_i + \frac{\eta}{n} {F_V} \sum_j \bm{x}_j ) \cdot \right. \\
&\left.  \cdot \frac{ \frac{\eta}{n} \left( \sum_j \bm{x}_j^T {F_V}^T (I -\frac{\eta}{n} \bm{x}_i \sum_\ell \bm{x}_\ell^T {F_V} ) \right)}
{\| \bm{x}_i +  \frac{\eta}{n} {F_V} \sum_j \bm{x}_j \|^2 }\right) \delta_{ih}
\end{split}
\label{eq:Jacob-moja}
\end{equation}

Let us first express the series expansion of the normed term:
\[
\begin{split}
& \| \bm{x}_i +  \frac{\eta}{n} {F_V} \sum_j \bm{x}_j \| =  \left(  (  \bm{x}_i +  \eta \bm{y} )^T (  \bm{x}_i + \eta \bm{y}) \right)^{\frac{1}{2}}  \\
& = \left( 1 + 2  \eta \bm{x}_i ^T \bm{y} + \eta^2 \| \bm{y} \|^2   \right)^{\frac{1}{2}} \\
& \approx  1 + \frac{1}{2} \left( 2  \eta \bm{x}_i ^T \bm{y} + \eta^2 \| \bm{y} \|^2  \right) - \frac{1}{2}  \eta^2 ( \bm{x}_i^T \bm{y} ) ^2 + O(\eta^3)  \\
& =  1 + \frac{\eta}{n} \bm{x}_i^T {F_V} \sum_j \bm{x}_j \\
& + \frac{\eta^2}{2 n^2} \left( \sum_j \bm{x}_j^T {F_V}^T {F_V} \sum_j \bm{x}_j - ( \bm{x}_i^T {F_V} \sum_j \bm{x}_j)^2 \right) \! \!  + O(\eta^3) 
\end{split}
\]
where we have used the binomial series expansion ($ (1 + \xi)^{\frac{1}{2}}\approx 1 + \frac{\xi}{2} - \frac{ \xi^2}{8}  + O(\xi^3)  $), disregarding terms of order higher than 2 in $ \eta$.
Differentiating this term
\[
\begin{split}
&  \frac{\partial \| \bm{x}_i +  \frac{\eta}{n} {F_V} \sum_j \bm{x}_j \|}{\partial \bm{x}_h }  = \\
&  =  \frac{\eta}{n} \bm{x}_i^T {F_V}  + \frac{\eta^2}{n^2}  \sum_j \bm{x}_j^T {F_V}^T ( I - \bm{x}_i \bm{x}_i^T ) {F_V}   \\
& + \left( \frac{\eta}{n} \sum_j \bm{x}_j^T {F_V}^T - \frac{\eta^2}{n^2}  \sum_j \bm{x}_j^T {F_V}^T \bm{x}_i \sum_\ell \bm{x}_\ell^T {F_V} \right) \delta_{ih}
\end{split}
\]
Inserting this expression into
\[
\begin{split}
 \frac{\partial f_i(\bm{x})}{\partial \bm{x}_h}   =& \frac{(I \delta_{ih} + \frac{\eta}{n} {F_V})  \| \bm{x}_i +  \frac{\eta}{n} {F_V} \sum_j \bm{x}_j \|}
{\| \bm{x}_i +  \frac{\eta}{n} {F_V} \sum_j \bm{x}_j \|^2} \\
&  - \frac{ (  \bm{x}_i +  \frac{\eta}{n} {F_V} \sum_j \bm{x}_j )  \frac{\partial \| \bm{x}_i +  \frac{\eta}{n} {F_V} \sum_j \bm{x}_j \|}{\partial \bm{x}_h }   }
{\| \bm{x}_i +  \frac{\eta}{n} {F_V} \sum_j \bm{x}_j \|^2}
\end{split}
\]
the result follows.
\hfill \vrule height 5pt width 5pt depth 0pt \medskip

\label{lem:moja-F-eigenvalues}
For the system \eqref{eq:update-moja}, under Assumption~\ref{ass:V-sym}, at a consensus equilibrium $ \bm{x}_i=\bm{v}_k $ $\forall \, i$ the Jacobian $ J(\bm{x}) $ has the following 3 classes of eigenvalues:
\begin{enumerate}
\item if $ 1+ \eta \lambda_k >0$, $ \frac{1-\eta \lambda_k + \eta^2 \lambda_k^2 }{1+ \eta \lambda_k } $ of multiplicity $ n$, while if $ 1+ \eta \lambda_k <0 $, $ \frac{-1-3 \eta \lambda_k + \eta^2 \lambda_k^2 }{1+ \eta \lambda_k } $ of multiplicity $ 1$ and $ \frac{-1-\eta \lambda_k + \eta^2 \lambda_k^2 }{1+ \eta \lambda_k } $ of multiplicity $ n-1$.
\item $ \frac{1+ \eta \lambda_h }{| 1+ \eta \lambda_k |} $ of multiplicity 1, $ h=1, \ldots, k-1, k+1, \ldots, d$. 
\item $  \frac{1 }{| 1+ \eta \lambda_k |} $ of multiplicity $ nd-d-n+1$.
\end{enumerate}

\label{lem:moja-consensus-stab}
For the system \eqref{eq:update-moja}, under Assumption~\ref{ass:V-sym}, and, if $ - \lambda_d > \lambda_1 $,  for $ \eta< \frac{2}{ |\lambda_1 + \lambda_d |} $, then the principal consensus equilibrium point, $ \bm{x}_i=\bm{v}_1 $ $\forall \, i$, is asymptotically stable.
For $ k=2, \ldots, d $, the consensus equilibria $ \bm{x}_i=\bm{v}_k $ $\forall \, i$ are all unstable.

\label{lem:self-equil1}
The system \eqref{eq:update} has the following classes of equilibria
\begin{enumerate}
\item consensus: $ \bm{x}_i = \bm{v}_k $ $ \forall \, i$, and $ k=1, \ldots, d$;
\item bipartite consensus: $ \bm{x}_i = \pm \bm{v}_k $ $ \forall \, i$ and $ k=1, \ldots, d$;
\item polygonal equilibria: $ \{ \bm{x}_i \in \mathbb{S}^{d-1} \; \text{s.t.} \;  {F_V} \sum_{j=1}^n A_{ij}(\bm{x}) \bm{x}_j =0\} $, $ i=1, \ldots, n$;
\item clustering equilibria: $  \{ \bm{x}_i \in \mathbb{S}^{d-1} \; \text{s.t.} \;  \varphi_i \bm{x}_i  = {F_V} \sum_{j=1}^n A_{ij}(\bm{x}) \bm{x}_j   \}$ for some scalars $ \varphi_i$, $ i=1, \ldots, n$, $ k=1, \ldots, d$.
\end{enumerate}

\label{lem:cons-Aij}
For a consensus state $ \bm{x}_i = \bm{v}_k $ $ \forall \, i$ we have $ A_{ij}(\bm{x}) = \frac{1}{n} $, i.e., the attention matrix $ A(\bm{x}) $ is the rank-1 uniform matrix $ A(\bm{x})  =\frac{1}{n} \mathds{1} \mathds{1}^T $. For a bipartite consensus state $ \bm{x}_i  = \pm \bm{v}_k $ $ \forall \, i$, the attention matrix $A(\bm{x})$ has rank 2.
For an $m$-clustering equilibrium $ \bm{x}$ the rank of $ A(\bm{x})$ is $m$.

\label{thm:stab-main-self}
For the self-attention dynamics~\eqref{eq:update}, under Assumption~\ref{ass:V-sym}, and, if $ -\lambda_d > \lambda_1 $, for $ \eta<  \frac{2}{ |\lambda_1 + \lambda_d |} $, the consensus equilibrium associated to the principal eigenvector $ \bm{v}_1 $ of ${F_V}$ is always locally asymptotically stable, while the other consensus equilibria $ \bm{v}_k$, $ k=2, \ldots, d $, are all unstable. 
A bipartite consensus equilibrium $ \bm{x}_i = \pm \bm{v}_k$ $ \forall \, i$ is asymptotically stable if $ \eta< \min\left( \frac{1}{\lambda_1 } , \, \frac{1}{ |\lambda_d |} \right) $ and the following inequalities are all satisfied
\begin{enumerate}
\item  
$ \frac{ |1 - (1-\eta \lambda_k \gamma_i^k)  \eta  \lambda_k\gamma_i^k | } {1+ \eta \lambda_k \gamma_i^k} <1 $, $ i =1,2 $;  
\item  $  a_j^k d_j^k - b_j^k c_j^k < 1 $ and $ a_j^k + d_j^k <1+ a_j^k d_j^k - b_j^k c_j^k $, $\, \forall \, j=1, \ldots, k-1, k+1,\ldots,  d $, where
 \begin{equation}
 \begin{split}
 a_j^k & = \frac{ 1+ \eta n_ 1 \frac{\alpha_1^k}{\beta_1^k}  \lambda_j  }{1+ \eta \lambda_k \gamma_1^k} , \qquad 
 b_j^k  = \frac{ \eta n_2 \frac{\alpha_2^k}{\beta_1^k}  \lambda_j  }{1+ \eta \lambda_k \gamma_1^k}, \\
 c_j^k  & = \frac{ \eta n_1 \frac{\alpha_2^k}{\beta_2^k}   \lambda_j  }{1+ \eta \lambda_k \gamma_2^k} , \qquad 
 d_j^k  =\frac{  1+  \eta n_ 2 \frac{\alpha_1^k}{\beta_2^k}   \lambda_j  }{1+ \eta \lambda_k \gamma_2^k  }
 \end{split}
 \label{eq:a-d} 
 \end{equation}
 \item $  \frac{1}{1+ \eta \lambda_k \gamma_i^k} <1$, $ i=1,2$.
 \end{enumerate}

All polygonal equilibria are unstable.

\label{lem:Jacob-self}
The Jacobian of  \eqref{eq:update}, $ J(\bm{x}) =  \frac{\partial f(\bm{x})}{\partial \bm{x}} = \begin{bmatrix} \frac{\partial f_i(\bm{x})}{\partial \bm{x}_h}  \end{bmatrix} $, has the following blocks:
 \begin{equation}
 \label{eq:jacon-atten1}
 \begin{split}
&   \frac{\partial f_i(\bm{x})}{\partial \bm{x}_h}  =   
 \frac{I \delta_{ih} + \eta {F_V} \left( \sum_j  \bm{x}_j  \frac{\partial A_{ij} (\bm{x}) }{\partial \bm{x}_h}    + A_{ih}(\bm{x}) I\right) }{\chi(\bm{x}) } \\
& \quad  -  \frac{  \left(  \bm{x}_i  + \eta {F_V} \sum_j A_{ij}(\bm{x}) \bm{x}_j \right)  \frac{\partial }{\partial \bm{x}_h}  \chi(\bm{x}) } {\chi(\bm{x})^2 }
\end{split}
 \end{equation}
 where
 \begin{equation}
 \begin{split}
 & \frac{\partial A_{ij} (\bm{x}) }{\partial \bm{x}_h}  
  =  \Bigg(-  \bm{x}_i^T {F_Q}^T {F_K} A_{ih}(\bm{x})  +  \bm{x}_i^T {F_Q}^T {F_K}  \delta_{jh}  \\
  & + \left( \bm{x}_j^T {F_K}^T {F_Q}  - \sum_\ell \bm{x}_\ell^T {F_K}^T {F_Q} A_{i\ell} (\bm{x}) \right) \delta_{ih} \Bigg) A_{ij} (\bm{x})
  \end{split}
 \label{eq:partial-A}
 \end{equation}
and
\begin{equation}
\label{eq:Jac-attent1}
\begin{split}
& \frac{\partial \chi(\bm{x})}{\partial \bm{x}_h }  =  \left( \sum_j\bm{x}_j   \frac{\partial A_{ij}(\bm{x})}{\partial \bm{x}_h}  + A_{ih}(\bm{x}) I\right)  \cdot \\
&  \cdot \left( \eta \bm{x}_i^T {F_V}  + \eta^2 \sum_j \bm{x}_j^T A_{ij}(\bm{x}) {F_V}^T (I - \bm{x}_i \bm{x}_i^T)  {F_V}   \right)  
\\
& + \left( \left(  \eta - \eta^2    \bm{x}_i^T  {F_V} \sum_j A_{ij}(\bm{x}) \bm{x}_j \right)  \sum_j A_{ij}(\bm{x}) \bm{x}_j^T {F_V}^T  \right) \delta_{ih}
\end{split}
\end{equation}

\label{lem:lin-stab-self1}
At a consensus point $ \bm{v}_k$, the eigenvalues of the Jacobian matrix $ J(\bm{v}_k) $ are those indicated in Lemma~\ref{lem:moja-F-eigenvalues}.
In particular, under Assumption~\ref{ass:V-sym}, and, if $ -\lambda_d > \lambda_1 $, for $ \eta<  \frac{2}{ |\lambda_1 + \lambda_d |} $, the consensus point $ \bm{x}_i =\bm{v}_1$ $ \forall\, i$ is locally asymptotically stable for \eqref{eq:update}, while the remaining consensus equilibria $ \bm{x}_i= \bm{v}_k$ $ \forall \, i $, with $ k= 2, \ldots, d $, are all unstable.

\label{lem:Jac-bip-cons}
At a bipartite consensus point $ \pm  \bm{v}_k $, the Jacobian $ J(\pm\bm{v}_k) $ is given by 
\[
\begin{split}
J(\pm\bm{v}_k) & = 
 \begin{bmatrix} 
J_o^{11} & \ldots &  J_o^{11} &  J_o^{12}   & \ldots &  J_o^{12} \\ 
\vdots & & \vdots & \vdots & & \vdots \\
J_o^{11} & \ldots &  J_o^{11} &  J_o^{12}   & \ldots &  J_o^{12} \\ 
J_o^{21} & \ldots &  J_o^{21} &  J_o^{22}   & \ldots &  J_o^{22} \\ 
\vdots & & \vdots & \vdots & & \vdots \\
J_o^{21} & \ldots &  J_o^{21} &  J_o^{22}   & \ldots &  J_o^{22} \\ 
 \end{bmatrix} \\
&  +
  \begin{bmatrix} J_d^1 & \\ &  \ddots \\ & &  J_d^1 \\
& & &  J_d^2 \\ & & & & \ddots \\ & & & & &  J_d^2   \end{bmatrix} 
,
 \end{split}
\]
where
\begin{equation}\label{eq:J_bip}
 \begin{split}
 J_o^{11}& =  \frac{
  \eta  \frac{\alpha_1^k}{\beta_1^k}}
{1+ \eta \lambda_k \gamma_1^k}  \Big(\sigma_1  {F_V} - \lambda_k \bm{v}_k \bm{v}_k^T  \\
& \quad -   ( 1-\sigma_1) (1-\gamma_1^k) \lambda_k \bm{v}_k \bm{v}_k^T {F_Q}^T {F_K}  \Big) \\
 J_o^{12} & =  \frac{
  \eta  \frac{\alpha_2^k}{\beta_1^k} }
{1+ \eta \lambda_k \gamma_1^k}  \Big( \sigma_1 {F_V} - \lambda_k \bm{v}_k \bm{v}_k^T   \\
& \quad + (1- \sigma_1) (1+\gamma_1^k) \lambda_k \bm{v}_k \bm{v}_k^T {F_Q}^T {F_K}  \Big) 
 \\
  J_o^{21} &  =  \frac{
  \eta  \frac{\alpha_2^k}{\beta_2^k} }
{1+ \eta \lambda_k \gamma_2^k}  \Big( \sigma_2 {F_V} - \lambda_k \bm{v}_k \bm{v}_k^T \\
& \quad   +  (1-\sigma_2) (1+\gamma_2^k) \lambda_k \bm{v}_k \bm{v}_k^T {F_Q}^T {F_K}  \Big) 
 \\
   J_o^{22} & =    \frac{
  \eta  \frac{\alpha_1^k}{\beta_2^k} }
{1+ \eta \lambda_k \gamma_2^k}  \Big( \sigma_2 {F_V} - \lambda_k \bm{v}_k \bm{v}_k^T   \\
& \quad  - (1-\sigma_2) (1-\gamma_2^k) \lambda_k \bm{v}_k \bm{v}_k^T {F_Q}^T {F_K} \Big) 
 \\
 J_d^1 &  = \frac{\sigma_1 I - ( 1- \sigma_1) \eta (1-(\gamma_1^k)^2) \lambda_k \bm{v}_k \bm{v}_k^T {F_Q}^T {F_K}}
 {1+ \eta \lambda_k \gamma_1^k} \\
 & \quad - \frac{  (1-\eta \lambda_k \gamma_1^k)  \eta  \lambda_k \gamma_1^k  \bm{v}_k \bm{v}_k^T }
 {1+ \eta \lambda_k \gamma_1^k} \\
  J_d^2 &  = \frac{\sigma_2 I -(1-\sigma_2)  \eta (1-(\gamma_2^k)^2) \lambda_k \bm{v}_k \bm{v}_k^T {F_Q}^T {F_K} }
{1+ \eta \lambda_k \gamma_2^k} \\
& \quad  -\frac{ (1-\eta \lambda_k \gamma_2^k) \eta  \lambda_k \gamma_2^k  \bm{v}_k \bm{v}_k^T }
{1+ \eta \lambda_k \gamma_2^k} \\
 \end{split}
 \end{equation}
 with $ \sigma_1 = {\rm sgn}({1+ \eta \lambda_k \gamma_1^k}) $ and $ \sigma_2 = {\rm sgn}({1+ \eta \lambda_k \gamma_2^k}) $.

Some tedious but elementary calculations yield:
 \[
 \left.  {F_V} \sum_j A_{ij}(\bm{x}) \bm{x}_j  \right|_{\bm{x}_{i,j} = \pm \bm{v}_k} = \begin{cases} 
 \gamma_1^k \lambda_k \bm{v}_k &  \text{ if } \; \; i \in \mathcal{V}_1 \\
- \gamma_2^k \lambda_k \bm{v}_k &  \text{ if } \; \; i \in \mathcal{V}_2 
\end{cases}
\]
\[
\begin{split}
 &\left. \bm{x}_i^T  {F_V} \sum_j A_{ij}(\bm{x}) \bm{x}_j  \right|_{\bm{x}_{i,j} = \pm \bm{v}_k} = \\                                                  
& \qquad \qquad = \begin{cases} \bm{v}_k^T {F_V} \gamma_1^k \bm{v}_k = \lambda_k \gamma_1^k &\!\!\!\! \text{ if } \;  i \in \mathcal{V}_1 \\
  - \bm{v}_k^T {F_V} (- \gamma_2^k) \bm{v}_k =  \lambda_k \gamma_2^k &\!\!\!\!  \text{ if } \;  i \in \mathcal{V}_2 
  \end{cases}
  \end{split}
  \]
  Since $ \bm{v}_k^T (I - \bm{v}_k \bm{v}_k^T) =0 $, it is
\[
\left. \sum_j \bm{x}_j^T A_{ij}(\bm{x}) {F_V}^T (I - \bm{x}_i \bm{x}_i^T)  {F_V} \right|_{\bm{x}_{i,j} = \pm \bm{v}_k} =0 .
\]
For the derivatives of the attention matrix, we have
\[
\begin{split}
&  \frac{\partial A_{ij}(\bm{x})}{\partial \bm{x}_h}  =\\
& = \begin{cases}
 \bullet\;  \text{if } \; \; i  \in \mathcal{V}_1, \; h \in \mathcal{V}_1, \;  j \in \mathcal{V}_1 : \\
 \left( - \frac{\alpha_1^k}{\beta_1^k} + \delta_{jh}\right) \frac{\alpha_1^k}{\beta_1^k} \bm{v}_k^T {F_Q}^T {F_K} 
+ \left(( 1 -\gamma_1^k) \frac{\alpha_1^k}{\beta_1^k}   \bm{v}_k^T {F_K}^T {F_Q} \right) \delta_{ih} \\  
\bullet\;  \text{if } \; \; i \in \mathcal{V}_1 ,\;  h \in \mathcal{V}_1 , \; j\in \mathcal{V}_2 \\
- \frac{\alpha_1^k}{\beta_1^k}  \frac{\alpha_2^k}{\beta_1^k}  \bm{v}_k^T {F_Q}^T {F_K} 
-( 1 +\gamma_1^k) \frac{\alpha_2^k}{\beta_1^k}  \left( \bm{v}_k^T {F_K}^T {F_Q} \right) \delta_{ih} \\
\bullet\;  \text{if } \; \; i \in \mathcal{V}_1, \; h\in \mathcal{V}_2, \;  j \in \mathcal{V}_1 \\
- \frac{\alpha_2^k}{\beta_1^k} \frac{\alpha_1^k}{\beta_1^k} \bm{v}_k^T {F_Q}^T {F_K} \\
\bullet\;  \text{if }  \; \; i \in \mathcal{V}_1, \; h\in \mathcal{V}_2 , \;  j \in \mathcal{V}_2  \\
\left( - \frac{\alpha_2^k}{\beta_1^k} + \delta_{jh}\right) \frac{\alpha_2^k}{\beta_1^k} \bm{v}_k^T {F_Q}^T {F_K} \\
\bullet\;  \text{if }  \; \; i \in \mathcal{V}_2, \; h \in \mathcal{V}_1, \; j \in \mathcal{V}_1  \\
\left(  \frac{\alpha_2^k}{\beta_2^k} - \delta_{jh}\right) \frac{\alpha_2^k}{\beta_2^k} \bm{v}_k^T {F_Q}^T {F_K} \\
\bullet\;  \text{if }  \; \; i \in \mathcal{V}_2, \; h \in \mathcal{V}_1 , \;  j \in \mathcal{V}_2  \\
  \frac{\alpha_2^k}{\beta_2^k}  \frac{\alpha_1^k}{\beta_2^k} \bm{v}_k^T {F_Q}^T {F_K} \\
\bullet\;  \text{if } \; \; i  \in \mathcal{V}_2, \; h \in \mathcal{V}_2, \;  j \in \mathcal{V}_1  \\
 \frac{\alpha_1^k}{\beta_2^k}  \frac{\alpha_2^k}{\beta_2^k} \bm{v}_k^T {F_Q}^T {F_K} 
+ \left(( 1 +\gamma_2^k) \frac{\alpha_2^k}{\beta_2^k}   \bm{v}_k^T {F_K}^T {F_Q} \right) \delta_{ih} \\
\bullet\; \text{if } \; \; i  \in \mathcal{V}_2, \; h \in \mathcal{V}_2, \;  j \in \mathcal{V}_2 \\
\left(  \frac{\alpha_1^k}{\beta_2^k} - \delta_{jh} \right) \frac{\alpha_1^k}{\beta_2^k} \bm{v}_k^T {F_Q}^T {F_K}  - \left(( 1 -\gamma_2^k) \frac{\alpha_1^k}{\beta_2^k}   \bm{v}_k^T {F_K}^T {F_Q} \right) \delta_{ih} \\
\end{cases}
\end{split}
\]
and hence
\[
\begin{split}
&\sum_j \bm{x}_j   \frac{\partial A_{ij}(\bm{x})}{\partial \bm{x}_h}  = \\
& = \begin{cases}
\bullet\;  \text{if } \; \; i  \in \mathcal{V}_1, \; h \in \mathcal{V}_1\\
\left(  \frac{\alpha_1^k}{\beta_1^k} (1 - \gamma_1^k ) + (1-(\gamma_1^k)^2 ) \delta_{ih} \right) \bm{v}_k  \bm{v}_k^T {F_Q}^T {F_K}  \\
\bullet\; \text{if } \; \; i  \in \mathcal{V}_1, \; h \in \mathcal{V}_2\\ 
-  \frac{\alpha_2^k}{\beta_1^k} (1 + \gamma_1^k ) \bm{v}_k \bm{v}_k^T {F_Q}^T {F_K}   \\
\bullet\;  \text{if } \; \; i  \in \mathcal{V}_2, \; h \in \mathcal{V}_1\\
-\frac{\alpha_2^k}{\beta_2^k} (1 + \gamma_2^k ) \bm{v}_k  \bm{v}_k^T {F_Q}^T {F_K}  \\
\bullet\;  \text{if } \; \; i  \in \mathcal{V}_2, \; h \in \mathcal{V}_2\\
\left(  \frac{\alpha_1^k}{\beta_2^k} (1 - \gamma_2^k ) + (1-(\gamma_2^k)^2 )  \delta_{ih} \right)  \bm{v}_k \bm{v}_k^T {F_Q}^T {F_K}   \\
\end{cases}
\end{split}
\]
Concerning the normed terms, 
\[
\begin{split}
 \left. \chi(\bm{x}) \right|_{\bm{x}_{i,j} = \pm \bm{v}_k} = \begin{cases}
| 1+ \eta \lambda_k \gamma_1^k | & \text{if } \; \; i  \in \mathcal{V}_1 \\
| 1+ \eta \lambda_k \gamma_2^k | & \text{if } \; \; i  \in \mathcal{V}_2
\end{cases}
\end{split}
\]
