\label{lem:lin-stab-self2}
When $ \eta< \min\left( \frac{1}{\lambda_1 } , \, \frac{1}{ | \lambda_d |} \right) $, at a bipartite consensus point $ \pm  \bm{v}_k $, the eigenvalues of the Jacobian $ J(\pm\bm{v}_k) $ are                                                                                                   
 \begin{enumerate}
 \item 
  $ \frac{ 1 - (1-\eta \lambda_k \gamma_1^k)  \eta  \lambda_k\gamma_1^k  }
 {1+ \eta \lambda_k \gamma_1^k}\  $ of multiplicity $ n_1$, and  $ \frac{ 1 - (1-\eta \lambda_k \gamma_2^k)  \eta  \lambda_k\gamma_2^k  }
 {1+ \eta \lambda_k \gamma_2^k}\  $  of multiplicity $ n_2$.
 \item $ \mu_{j,\pm}^k =  \frac{1}{2} \Big( a_j^k+ d_j^k \pm \sqrt{ (a_j^k-d_j^k)^2 + 4 c_j^kb_j^k } \Big) $ for $ j=1, \ldots, k-1, k+1,\ldots, d $, where $ a_j^k$, $ b_j^k$, $ c_j^k $ and $ d_j^k$ are given by \eqref{eq:a-d}.


 \item   $  \frac{1}{1+ \eta \lambda_k \gamma_1^k} $ and $  \frac{1 }{1+ \eta \lambda_k \gamma_2^k} $, of total multiplicity $ nd -n -2d +2 $.
 \end{enumerate}

For $ J(\pm \bm{v}_k) $ there are 3 classes of eigenvectors:
 \begin{enumerate}
 \item                                                                                                    
 If $ 1+ \eta \lambda_k \gamma_i^k >0$, $i=1, 2$, then choose $ \bm{p}^\ell = [ \,\underbrace{0 \, \ldots \, 0}_{\ell-1} \, \bm{v}_k^T \, \underbrace{0 \, \ldots \, 0}_{n- \ell} \,]^T$. There are $ n$ such eigenvectors, and they are obviously all orthogonal to each other. For $\ell \leq n_1 $ it is 
  \[
 \begin{cases}
 J_o^{11} \bm{v}_k & =  \frac{
  \eta  \frac{\alpha_1^k}{\beta_1^k} \left( {F_V} - \lambda_k \bm{v}_k \bm{v}_k^T \right)  
 }
{1+ \eta \lambda_k \gamma_1^k} \bm{v}_k 
=  \frac{ \eta  \frac{\alpha_1^k}{\beta_1^k} \left( \lambda_k \bm{v}_k  - \lambda_k \bm{v}_k \right)}
{1+ \eta \lambda_k \gamma_1^k} =0
\\
   J_o^{21}  \bm{v}_k &  =  \frac{
  \eta  \frac{\alpha_2^k}{\beta_2^k}  \left( {F_V} - \lambda_k \bm{v}_k \bm{v}_k^T \right)  
}
{1+ \eta \lambda_k \gamma_2^k} \bm{v}_k = \frac{
  \eta  \frac{\alpha_2^k}{\beta_2^k}   \left( \lambda_k \bm{v}_k  - \lambda_k \bm{v}_k \right)  
}
{1+ \eta \lambda_k \gamma_2^k} =0
\\
 J_d^1 \bm{v}_k &  = \frac{ I -(1-\eta \lambda_k \gamma_1^k)  \eta  \lambda_k \gamma_1^k \bm{v}_k \bm{v}_k^T }
 {1+ \eta \lambda_k \gamma_1^k} \bm{v}_k \\
&  = \frac{ 1 -  (1-\eta \lambda_k \gamma_1^k) \eta  \lambda_k \gamma_1^k }
 {1+ \eta \lambda_k \gamma_1^k}\bm{v}_k 
 \\
   \end{cases}
\]
meaning that 
\[
J(\pm \bm{v}_k ) \bm{p} =\frac{ 1 -(1-\eta \lambda_k \gamma_1^k) \eta \lambda_k  \gamma_1^k  }
 {1+ \eta \lambda_k \gamma_1^k}\ \bm{p}
\]
i.e., $ \frac{ 1 - (1-\eta \lambda_k \gamma_1^k)  \eta  \lambda_k\gamma_1^k  }
 {1+ \eta \lambda_k \gamma_1^k}\  $ is an eigenvalue of $ J(\pm \bm{v}_k)$ of multiplicity $ n_1$.
For $ \ell> n_1 $, similar calculations give
\[
 J_o^{12} \bm{v}_k = J_o^{22} \bm{v}_k =0, \;\; J_d^2 \bm{v}_k = \frac{ 1 -  (1-\eta \lambda_k \gamma_2^k) \eta  \lambda_k \gamma_2^k }
 {1+ \eta \lambda_k \gamma_2^k}\bm{v}_k 
 \]
 i.e., $ \frac{ 1 - (1-\eta \lambda_k \gamma_2^k)  \eta  \lambda_k\gamma_2^k  }
 {1+ \eta \lambda_k \gamma_2^k}\  $ is an eigenvalue of $ J(\pm \bm{v}_k)$ of multiplicity $ n_2$.




\item Second class: Consider $ d-1$  vectors  $ \bm{q}^h $ s.t. $ \bm{q}^h =[\, \underbrace{ (\bm{w}_1^h)^T \, \ldots  \,  (\bm{w}_1^h)^T}_{n_1 \; \text{times}} \; \underbrace{(\bm{w}_2^h)^T \, \ldots  \, (\bm{w}_2^h)^T}_{n_2 \; \text{times}} ]^T $, with 
$ \bm{w}_1^h = \sum_{j=1}^d \xi_j^{h,1} \bm{v}_j $ and $ \bm{w}_2^h = \sum_{j=1}^d \xi_j^{h,2} \bm{v}_j $.
Choose $ \bm{w}_i^h $ s.t. $ \xi_k^{h,i}=0$, so that $ \bm{v}_k^T \bm{w}_i^h =0$.
We have 
\[
\begin{split} 
J_o^{11} \bm{w}_1^h & = \frac{\eta  \frac{\alpha_1^k}{\beta_1^k}   \sum_{j\neq k } \lambda_j \xi_j^{h,1} \bm{v}_j }{1+ \eta \lambda_k \gamma_1^k} \\
J_o^{12} \bm{w}_2^h & = \frac{\eta  \frac{\alpha_2^k}{\beta_1^k}  \sum_{j\neq k } \lambda_j \xi_j^{h,2} \bm{v}_j }{1+ \eta \lambda_k \gamma_1^k} \\
J_o^{21} \bm{w}_1^h & = \frac{\eta  \frac{\alpha_2^k}{\beta_2^k}  \sum_{j\neq k } \lambda_j \xi_j^{h,1} \bm{v}_j }{1+ \eta \lambda_k \gamma_2^k} \\
J_o^{22} \bm{w}_2^h & = \frac{\eta  \frac{\alpha_1^k}{\beta_2^k}  \sum_{j\neq k } \lambda_j \xi_j^{h,2} \bm{v}_j }{1+ \eta \lambda_k \gamma_2^k} \\
\end{split}
\]
and
\[
\begin{split} 
J_d^{1} \bm{w}_1^h & = \frac{ \bm{w}_1^h }{1+ \eta \lambda_k \gamma_1^k} \\
J_d^{2} \bm{w}_2^h & = \frac{ \bm{w}_2^h  }{1+ \eta \lambda_k \gamma_2^k}
\end{split}
\]
The $ \bm{q}^h $ are obtained solving the algebraic equation  $ J(\pm \bm{v}_k) \bm{q}^h = \mu \bm{q}^h $ where also the eigenvalue $ \mu $ is an unknown.
Expanding we obtain a block of $ n_1 $ identical equations
\[
\begin{split}
 \frac{  \sum_{j\neq k }  \left(  \eta n_ 1 \frac{\alpha_1^k}{\beta_1^k} \xi_j^{h,1}  +  \eta  n_2 \frac{\alpha_2^k}{\beta_1^k}   \xi_j^{h,2} \right)  \lambda_j  \bm{v}_j +  \sum_{j\neq k }  \xi_j^{h,1}   \bm{v}_j }{1+ \eta \lambda_k \gamma_1^k} \\
  = \mu  \sum_{j\neq k }  \xi_j^{h,1}   \bm{v}_j 
 \end{split}
 \]
 and another of $ n_2 $ identical equations
 \[
 \begin{split}
 \frac{  \sum_{j\neq k }  \left( \eta n_ 1 \frac{\alpha_2^k}{\beta_2^k}  \xi_j^{h,1}  +  \eta  n_2 \frac{\alpha_1^k}{\beta_2^k}  \xi_j^{h,2} \right)  \lambda_j  \bm{v}_j +  \sum_{j\neq k }  \xi_j^{h,2}   \bm{v}_j }{1+ \eta \lambda_k \gamma_2^k} \\
  = \mu  \sum_{j\neq k }  \xi_j^{h,2}   \bm{v}_j  \end{split}
 \]
 whose solution provides both the desired eigenvector $ \bm{w}_i^h $ and the associated eigenvalues $ \mu$. 
Projecting these equations along the eigenvector $ \bm{v}_j $ and rearranging
\[
\begin{split}
\Big(  \overbrace{ 
 \frac{ 1+ \eta n_ 1 \frac{\alpha_1^k}{\beta_1^k}  \lambda_j  }{1+ \eta \lambda_k \gamma_1^k} }^{=a_j^k} - \mu \Big)  \xi_j^{h,1} + 
\Big(  \overbrace{ 
 \frac{ \eta n_2 \frac{\alpha_2^k}{\beta_1^k}  \lambda_j  }{1+ \eta \lambda_k \gamma_1^k} }^{=b_j^k} \Big)  \xi_j^{h,2} =0 \\
\Big( \underbrace{ \frac{ \eta n_1 \frac{\alpha_2^k}{\beta_2^k}   \lambda_j  }{1+ \eta \lambda_k \gamma_2^k}  }_{=c_j^k} \Big) \xi^{h,1}_j  
+ \Big( \underbrace{ \frac{  1+  \eta n_ 2 \frac{\alpha_1^k}{\beta_2^k}   \lambda_j  }{1+ \eta \lambda_k \gamma_2^k  } }_{=d_j^k} - \mu  \Big)  \xi^{h,2}_j  & = 0.
\end{split}
\]
Notice that $ a_j^k$, $b_j^k $, $ c_j^k$ and $ d_j^k $ are independent of the index $h$, hence, to avoid repeated identical algebraic equations, we can take $ h=j$ and drop one index in the $ \xi_j^{h,i}$ variables: $ \xi_j^{h,i} = \xi_j^i $, obtaining
\[
\begin{split}
(a_j^k-\mu) \xi^1_j  +b_j^k  \xi^2_j & =0 \\
c_j^k \xi^1_j  + (d_j^k-\mu)   \xi^2_j  & =0 ,
\end{split}
\]
which leads to the formula for the eigenvalues $ \mu_{j, \pm}^k = \frac{1}{2} \Big( a_j^k+ d_j^k \pm \sqrt{ (a_j^k-d_j^k)^2 + 4 c_j^kb_j^k } \Big) $. 

The relationship between the components of the two vectors $ \bm{w}_\ell^j $ is then $  \xi^2_j = -\frac{a_j^k- \mu_{j, \pm}^k}{b_j^k} \xi^1_j$.
Notice that for each $ \bm{q}^j $ there are two eigenvalues $ \mu_{j, \pm}^k$, for a total of $ 2 (d-1)$ eigenvalues in this class.


\item 
The third class contains the $ nd - n - 2d+2 $ remaining eigenvectors subdivided into two groups: $ \bm{r}_1 = \begin{bmatrix} \epsilon_1 \bm{v}_h^T & \ldots &  \epsilon_{n_1} \bm{v}_h^T & 0 & \ldots & 0 \end{bmatrix}^T$ and $ \bm{r}_2 = \begin{bmatrix} 0 & \ldots & 0  & \varepsilon_1 \bm{v}_h^T & \ldots & \varepsilon_{n_2}  \bm{v}_h^T \end{bmatrix}^T$ where $ \bm{v}_h $ is an eigenvector of ${F_V}$, $h \neq k $, and $ \sum_{j=1}^{n_1} \epsilon_j =0$, $ \sum_{j=1}^{n_2} \varepsilon_j =0$.
By construction, $ \bm{v}_k^T \bm{v}_h =0 $ and $ (\bm{w}_\ell^j)^T \bm{v}_h=0 $ for all  $ j=1, \ldots, k-1, k+1, \ldots, d $ and $ \ell =1,2$. 
Computing: 
\[
J(\pm \bm{v}_k ) \bm{r}_1
= \begin{bmatrix}  
 \frac{\eta \frac{\alpha_1^k}{\beta_1^k} \lambda_h  \left(\sum_{j=1}^{n_1} \epsilon_j \right) \bm{v}_h +  \epsilon_1 \bm{v}_h}{ 1+ \eta \lambda_k \gamma_1^k} \\ 
\vdots \\ 
 \frac{\eta \frac{\alpha_1^k}{\beta_1^k} \lambda_h  \left(\sum_{j=1}^{n_1} \epsilon_j \right) \bm{v}_h + \epsilon_{n_1} \bm{v}_h}{ 1+ \eta \lambda_k \gamma_1^k} \\ 
\frac{\eta \frac{\alpha_2^k}{\beta_2^k} \lambda_h   \left(\sum_{j=1}^{n_1} \epsilon_j \right) \bm{v}_h }{ 1+ \eta \lambda_k \gamma_2^k}  \\ 
\vdots \\
 \frac{\eta \frac{\alpha_2^k}{\beta_2^k} \lambda_h  \left(\sum_{j=1}^{n_1} \epsilon_j \right) \bm{v}_h }{ 1+ \eta \lambda_k \gamma_2^k} 
 \end{bmatrix} = \frac{1}{1+ \eta \lambda_k \gamma_1^k}  \bm{r}_1
 \]  
and, similarly, $ J(\pm \bm{v}_k ) \bm{r}_2 = \frac{1}{1+ \eta \lambda_k \gamma_2^k} \bm{r}_2$. 
\end{enumerate}
